import{_ as t,o as a,c as n,ah as i}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Client","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/client.md","filePath":"src/guide/client.md"}'),r={name:"guide/client.md"};function o(l,e,s,u,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="guide-—-client" tabindex="-1">Guide — Client <a class="header-anchor" href="#guide-—-client" aria-label="Permalink to &quot;Guide — Client&quot;">​</a></h1><p>Suivre vos projets, valider vos livrables, régler vos factures.</p><h2 id="votre-tableau-de-bord" tabindex="-1">Votre tableau de bord <a class="header-anchor" href="#votre-tableau-de-bord" aria-label="Permalink to &quot;Votre tableau de bord&quot;">​</a></h2><p>Après connexion, votre tableau de bord regroupe :</p><ul><li>le nombre total de vos projets, par statut (actif, suspendu, terminé) ;</li><li>vos jalons atteints et jalons en attente ;</li><li>vos projets récents, avec accès direct à leur fiche ;</li><li>vos échéances de facturation à venir, avec mise en évidence des factures en retard ;</li><li>les documents en attente de votre validation.</li></ul><h2 id="suivre-l-avancement-d-un-projet" tabindex="-1">Suivre l&#39;avancement d&#39;un projet <a class="header-anchor" href="#suivre-l-avancement-d-un-projet" aria-label="Permalink to &quot;Suivre l&#39;avancement d&#39;un projet&quot;">​</a></h2><p>Sur la fiche d&#39;un projet, la navigation à gauche regroupe les informations par thème :</p><ul><li><strong>Suivi</strong> — les phases du projet et leurs jalons, une vue Gantt de l&#39;ensemble, et le détail des tâches en cours.</li><li><strong>Collaboration</strong> — les documents partagés, l&#39;équipe affectée à votre projet et la messagerie.</li><li><strong>Finance</strong> — les signatures à effectuer, la facturation et, une fois formalisé, un éventuel avenant.</li></ul><p>À chaque jalon non facturable atteint, votre chef de projet peut laisser un <strong>compte-rendu</strong> visible depuis l&#39;onglet Suivi. Certains jalons incluent aussi un <strong>lien de démo</strong> vers une version fonctionnelle du projet à cette étape, quand c&#39;est pertinent pour votre type de projet.</p><h2 id="documents-et-livrables" tabindex="-1">Documents et livrables <a class="header-anchor" href="#documents-et-livrables" aria-label="Permalink to &quot;Documents et livrables&quot;">​</a></h2><p>Depuis l&#39;onglet <strong>Documents</strong> de votre projet :</p><ul><li>consultez les documents et livrables partagés par l&#39;équipe projet ;</li><li>déposez vos propres documents (cahier des charges, pièces administratives, retours) ;</li><li>validez un livrable ou laissez un commentaire directement depuis sa fiche — l&#39;équipe projet est notifiée de votre décision.</li></ul><h2 id="signature-electronique" tabindex="-1">Signature électronique <a class="header-anchor" href="#signature-electronique" aria-label="Permalink to &quot;Signature électronique&quot;">​</a></h2><p>Certains documents requièrent votre signature électronique, depuis l&#39;onglet <strong>Signatures</strong> :</p><ul><li>le <strong>bon de livraison</strong>, à la remise d&#39;un livrable ou d&#39;un équipement ;</li><li>l&#39;<strong>attestation de bonne fin d&#39;exécution</strong>, à la clôture du projet ;</li><li>un éventuel <strong>avenant</strong>, une fois que celui-ci a été formalisé par l&#39;administrateur (l&#39;onglet n&#39;apparaît qu&#39;à ce moment-là, pas pendant sa préparation).</li></ul><h2 id="facturation-et-paiement" tabindex="-1">Facturation et paiement <a class="header-anchor" href="#facturation-et-paiement" aria-label="Permalink to &quot;Facturation et paiement&quot;">​</a></h2><p>Depuis l&#39;onglet <strong>Facturation</strong> :</p><ul><li>consultez l&#39;échéancier de paiement de votre projet et le statut de chaque échéance (à venir, due, réglée) ;</li><li>téléchargez vos factures (acompte, intermédiaire, solde ou équipement selon le cas) — vous êtes notifié à leur envoi, avec un rappel avant l&#39;échéance ;</li><li>réglez une facture directement depuis la plateforme via Mobile Money (Flooz, T-Money) ou carte bancaire, ou déclarez un règlement par virement bancaire classique.</li></ul><div class="warning custom-block"><p class="custom-block-title">Facture impayée</p><p>Si une facture reste impayée au-delà du délai convenu, l&#39;accès à votre projet peut être suspendu par votre chef de projet ou l&#39;administrateur, jusqu&#39;à régularisation.</p></div><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Échangez avec l&#39;équipe projet via la messagerie intégrée, sans sortir de la plateforme. Vous recevez des notifications automatiques aux étapes clés : jalon atteint, livrable soumis, retard signalé, échéance de paiement due.</p>',21)])])}const v=t(r,[["render",o]]);export{m as __pageData,v as default};
